def _decode(token):
    # '~1' stands for '/' and '~0' stands for '~', decoded in that order.
    return token.replace('~1', '/').replace('~0', '~')


def _is_index(token):
    return bool(token) and all('0' <= c <= '9' for c in token)


def _tokens(pointer):
    if not pointer.startswith('/'):
        raise KeyError(pointer)
    return [_decode(t) for t in pointer[1:].split('/')]


def _step(node, token):
    if isinstance(node, list):
        if not _is_index(token):
            raise KeyError(token)
        index = int(token)
        if index >= len(node):
            raise KeyError(token)
        return node[index]
    if isinstance(node, dict):
        if token not in node:
            raise KeyError(token)
        return node[token]
    raise KeyError(token)


def resolve(doc, pointer):
    if pointer == '':
        return doc
    node = doc
    for token in _tokens(pointer):
        node = _step(node, token)
    return node


def set_at(doc, pointer, value):
    tokens = _tokens(pointer)
    node = doc
    for token in tokens[:-1]:
        node = _step(node, token)
    last = tokens[-1]
    if isinstance(node, list):
        if last == '-':
            node.append(value)
            return
        if not _is_index(last):
            raise KeyError(last)
        index = int(last)
        if index >= len(node):
            raise KeyError(last)
        node[index] = value
        return
    if isinstance(node, dict):
        node[last] = value
        return
    raise KeyError(last)

